'use strict';
labels.tools=['YOUR INSTANCE WORKBENCH','Launcher tools.'];
let launcherTools=[],activeTool=null;
function toolPrefs(){return state.settings.tools||{};}
function applyToolPrefs(){const p=toolPrefs();document.body.classList.toggle('compact-instances',!!p.compact);document.body.classList.toggle('reduce-motion',!!p.reduceMotion);document.body.classList.toggle('large-text',!!p.largeText);document.body.classList.toggle('hide-account-name',!!p.hideNames);if(p.rememberInstance===false)localStorage.removeItem('selected-instance');if(capePreview){capePreview.reducedMotion=!!p.reduceMotion;if(p.reduceMotion)capePreview.autoRotate=false;}}
function toolInstances(){let list=[...state.instances];const p=toolPrefs();if(p.favoritesOnly)list=list.filter(x=>x.favorite);if(p.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name));else if(p.sort==='version')list.sort((a,b)=>b.minecraft.localeCompare(a.minecraft,undefined,{numeric:true}));else list.sort((a,b)=>(b.lastPlayed||b.created)-(a.lastPlayed||a.created));return list;}
async function loadLauncherTools(){if(!launcherTools.length)launcherTools=await api('tools-list');drawLauncherTools();}
function drawLauncherTools(){const query=$('tools-search').value.trim().toLowerCase(),group=$('tools-group').value;const list=launcherTools.filter(t=>(!group||t.group===group)&&(!query||(t.name+' '+t.description).toLowerCase().includes(query)));$('tools-count').textContent=list.length+' / '+launcherTools.length+' tools';$('tools-grid').innerHTML=list.map(t=>'<article class="content-card tool-card"><span class="sponsor-badge">'+escape(t.group)+'</span><h3>'+escape(t.name)+'</h3><p>'+escape(t.description)+'</p><button class="button subtle" data-tool="'+escape(t.id)+'">'+(t.group==='Diagnostics'?'View report':t.group==='Folders'?'Open folder':'Open tool')+'</button></article>').join('')||empty('No matching tools.','Try another search or category.');$('tools-grid').querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>openLauncherTool(b.dataset.tool)));}
function openLauncherTool(id){activeTool=launcherTools.find(t=>t.id===id);$('tool-title').textContent=activeTool.name;$('tool-description').textContent=activeTool.description;$('tool-report').classList.add('hidden');$('tool-input-label').classList.toggle('hidden',!activeTool.input);$('tool-input-label').firstChild.textContent=(activeTool.input||'Value')+' ';$('tool-value').classList.toggle('hidden',!!activeTool.options);$('tool-choice').classList.toggle('hidden',!activeTool.options);if(activeTool.options){$('tool-choice').innerHTML=activeTool.options.map(o=>'<option>'+escape(o)+'</option>').join('');let v=id.startsWith('pref-')?toolPrefs()[id.slice(5)]:id==='favorite'?!!selected()?.favorite:undefined;if(v===undefined&&id==='pref-rememberInstance')v=true;if(v===undefined&&id==='pref-showDisabled')v=true;if(typeof v==='boolean')v=v?'Yes':'No';if(v===undefined&&activeTool.options.includes('No'))v='No';if(v!==undefined)$('tool-choice').value=v;}else $('tool-value').value=id==='rename'?selected()?.name||'':id==='notes'?selected()?.notes||'':id==='memory'?selected()?.launchOverrides?.memory||state.settings.memory:id==='resolution'?(selected()?.launchOverrides?.width||state.settings.width)+'x'+(selected()?.launchOverrides?.height||state.settings.height):id==='skin-png'?state.settings.offlineName||'Player':'';$('tool-submit').textContent=activeTool.group==='Diagnostics'?'Run report':'Continue';$('tool-dialog').showModal();}
$('tools-search').addEventListener('input',drawLauncherTools);$('tools-group').addEventListener('change',drawLauncherTools);
$('tool-form').addEventListener('submit',e=>{e.preventDefault();action(async()=>{if(!activeTool)return;const id=activeTool.id;if(!selected()&&!id.startsWith('pref-')&&id!=='restore')throw new Error('Select an instance first.');const r=await api('tools-run',{id,instanceId:selectedId,value:activeTool.options?$('tool-choice').value:$('tool-value').value});if(!r)return;if(r.report!==undefined){$('tool-report').textContent=typeof r.report==='string'?r.report:JSON.stringify(r.report,null,2);$('tool-report').classList.remove('hidden');return;}if(r.instance)selectedId=r.instance.id;await refresh();applyToolPrefs();if(id==='pref-readyProfile')$('ready-profile').value=toolPrefs().readyProfile||'balanced';if(page==='installed')await loadInstalled();$('tool-dialog').close();toast(r.message||'Tool completed.');});});
